<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>The Great Wave off Kanagawa — Low Poly 3D</title>
<style>
  html, body { margin: 0; padding: 0; overflow: hidden; background: #e8d9b0; }
  canvas { display: block; }
  #label {
    position: fixed; left: 16px; bottom: 12px;
    font-family: Georgia, 'Times New Roman', serif;
    color: #2b3a55; font-size: 13px; letter-spacing: 0.06em;
    opacity: 0.75; pointer-events: none;
  }
</style>
</head>
<body>
<div id="label">The Great Wave off Kanagawa · low poly</div>
<script type="importmap">
{ "imports": { "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js" } }
</script>
<script type="module">
import * as THREE from 'three';

// ---- Palette from the print (prussian blues, white foam, washi cream, ochre hulls) ----
const C = {
  washi:      0xf0e2c0,  // paper sky base
  skyTop:     0xe9dcb8,
  skyBottom:  0xd9c79c,
  ink:        0x1c2a4a,  // dark outline ink
  blueDeep:   0x1e3a6e,  // deepest prussian
  blueMid:    0x2e5b9e,
  blueLight:  0x7fb0d8,  // pale wash blue
  foam:       0xffffff,  // white foam
  foamShadow: 0xdfe9ee,
  hull:       0xd9a066,  // ochre boat hull
  hullDark:   0xa8703f,
  deck:       0xe8d5a8,
  fuji:       0xf2efe6,  // snow
  fujiShade:  0xb9c4cf,  // shaded snow
  fujiBase:   0x8a93a3,  // dark base band
};

const scene = new THREE.Scene();
scene.background = new THREE.Color(C.washi);
scene.fog = new THREE.Fog(C.washi, 60, 140);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 500);
camera.position.set(0, 7, 46);
camera.lookAt(0, 3, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
document.body.appendChild(renderer.domElement);

// ---- Lighting: soft, print-like, flat shading for the low-poly look ----
const hemi = new THREE.HemisphereLight(0xfff6e0, 0x8a93a3, 0.9);
scene.add(hemi);
const sun = new THREE.DirectionalLight(0xfff2d8, 0.8);
sun.position.set(-18, 30, 20);
scene.add(sun);
const fill = new THREE.DirectionalLight(0xcfe0f0, 0.35);
fill.position.set(20, 10, -10);
scene.add(fill);

function flat(color, opts = {}) {
  return new THREE.MeshStandardMaterial({
    color, flatShading: true, roughness: 0.9, metalness: 0.0, ...opts
  });
}

// ================= SKY =================
// Vertical gradient sky via a big plane with a shader-free vertex-color trick.
{
  const g = new THREE.PlaneGeometry(400, 200, 1, 8);
  const pos = g.attributes.position;
  const colors = [];
  const top = new THREE.Color(C.skyTop);
  const bot = new THREE.Color(C.skyBottom);
  for (let i = 0; i < pos.count; i++) {
    const t = (pos.getY(i) + 100) / 200; // 0 bottom -> 1 top
    const c = bot.clone().lerp(top, t);
    colors.push(c.r, c.g, c.b);
  }
  g.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  const m = new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.DoubleSide });
  const sky = new THREE.Mesh(g, m);
  sky.position.z = -80;
  scene.add(sky);
}

// ================= CLOUDS (puffy, low-poly) =================
const clouds = [];
function makeCloud(x, y, z, s) {
  const grp = new THREE.Group();
  const mat = flat(0xf3ead2, { roughness: 1 });
  const n = 5 + Math.floor(Math.random() * 3);
  for (let i = 0; i < n; i++) {
    const r = (1.2 + Math.random() * 1.6) * s;
    const geo = new THREE.IcosahedronGeometry(r, 0);
    const m = new THREE.Mesh(geo, mat);
    m.position.set((i - n / 2) * 1.6 * s, (Math.random() - 0.5) * 1.2 * s, (Math.random() - 0.5) * 1.5 * s);
    grp.add(m);
  }
  grp.position.set(x, y, z);
  scene.add(grp);
  clouds.push({ grp, speed: 0.15 + Math.random() * 0.2 });
}
makeCloud(-30, 22, -55, 1.4);
makeCloud(8, 26, -65, 1.8);
makeCloud(35, 20, -58, 1.2);
makeCloud(-8, 30, -70, 1.0);

